  "amusement": "idil/e800291ff82c.m4a",
  "My father watched with obvious amusement as I tried to fix the bicycle with the wrong tool.": "idil/41eb7291f7de.m4a",
  "bond": "idil/1d2bba5d0b80.m4a",
  "Working together on the farm every summer created a strong bond between the two cousins.": "idil/1ee974496839.m4a",
