  "involuntary": "idil/0c68bb72e951.m4a",
  "Blinking when something flies towards your eyes is an involuntary reaction that protects them.": "idil/48efe861d772.m4a",
  "hilarious": "idil/981a7d7069c9.m4a",
  "My uncle's attempt to dance at the wedding was hilarious, and he laughed at it more than anyone.": "idil/14415f3e12c5.m4a",
  "awkward": "idil/f7d4c2e58cb8.m4a",
  "There was an awkward silence after he asked her age in front of all her colleagues.": "idil/46cff62b51f7.m4a",
  "infectious": "idil/6aa1fc5a005e.m4a",
  "Our new teacher had such an infectious laugh that the whole class soon joined in.": "idil/637f212f8662.m4a",
  "uncontrollably": "idil/584456f6679a.m4a",
  "When the cold water hit him, he began to shiver uncontrollably.": "idil/650efe1cca49.m4a",
  "cheer up": "idil/1a65ba78828f.m4a",
