  "map out": "idil/2bca7130a28a.m4a",
  "Before the trip, we mapped out a route that kept us away from the busiest motorways.": "idil/fcafe3ce63a0.m4a",
  "look up": "idil/198925bb2ce6.m4a",
  "If you don't know where the town is, look it up in the atlas.": "idil/7f12458b7f4a.m4a",
  "folklore": "idil/8f6de928473e.m4a",
  "She grew up in a village where folklore was part of daily life, from wedding songs to stories about local spirits.": "idil/8d60b134eb6a.m4a",
  "tale": "idil/34edfb0961a6.m4a",
  "Almost every culture seems to have a tale about a clever little animal that outwits a much stronger one.": "idil/cd9e4c8fadff.m4a",
