  "borrow": "idil/72cd0a82a0c7.m4a",
  "Many playwrights have borrowed their plots from much older stories and simply changed the setting.": "idil/f77071b91de2.m4a",
  "oral": "idil/1a1fd23792b6.m4a",
  "Before writing spread, many communities kept their history alive through oral tradition.": "idil/419a4c63d40c.m4a",
  "wicked": "idil/9e38cc8bf3cb.m4a",
  "In the play, a wicked uncle locks the young prince in a tower and takes the crown for himself.": "idil/19ed8bb7d1e1.m4a",
  "timeless": "idil/f2026124fed3.m4a",
  "Some children's books have a timeless quality: my grandmother loved the same ones that I now read to my son.": "idil/2676d81ee32f.m4a",
