  "dyslexia": "idil/0976cb071f38.m4a",
  "Dyslexia has no connection with intelligence, and many people with it are highly creative thinkers.": "idil/3922835fbcdc.m4a",
  "cerebral": "idil/30534f34aea5.m4a",
  "A stroke occurs when the blood supply to part of the brain is interrupted, often by a blocked cerebral artery.": "idil/74efa1add6d4.m4a",
  "psychosis": "idil/89b6b9780444.m4a",
  "An episode of psychosis can be frightening, but many people recover well with early support.": "idil/6c556bf95f7b.m4a",
  "bipolar": "idil/45a9360afaec.m4a",
  "Bipolar disorder involves periods of very low mood that alternate with periods of unusually high energy.": "idil/4dda331f943c.m4a",
  "burnout": "idil/4829baec0d83.m4a",
  "Long shifts and staff shortages have left many nurses at serious risk of burnout.": "idil/179d7cf1d93d.m4a",
  "antidepressant": "idil/0b882860c894.m4a",
  "Antidepressants usually take several weeks to have a noticeable effect on mood.": "idil/97848ff5d9c8.m4a",
  "painkiller": "idil/811a2e4d8a0b.m4a",
  "Even common painkillers can cause harm if people take more than the recommended amount.": "idil/3c4411b2b816.m4a",
  "efficacy": "idil/4f43aa58724d.m4a",
  "Large clinical trials are needed to establish both the safety and the efficacy of a new drug.": "idil/cd925db3afb3.m4a",
  "side effect": "idil/816b2d5b79c7.m4a",
  "Drowsiness is a common side effect of some allergy medicines, so drivers are advised to be careful.": "idil/64029791350a.m4a",
  "dialysis": "idil/966ac4713e4b.m4a",
  "Patients on dialysis often need to visit a clinic several times a week for treatment.": "idil/4313d54eb14d.m4a",
  "regimen": "idil/19cb49368298.m4a",
  "Following a complicated drug regimen can be difficult for older patients who take several medicines.": "idil/bd6f90609866.m4a",
  "prosthesis": "idil/91d2f779a48e.m4a",
