  "physiotherapy": "idil/2043fbd30198.m4a",
  "After knee surgery, several weeks of physiotherapy are usually needed to restore strength and movement.": "idil/e81d5ea3b2ba.m4a",
  "tobacco": "idil/70178a609a4b.m4a",
  "Higher taxes on tobacco are one of the measures governments use to discourage smoking.": "idil/ad42a4ef9d76.m4a",
  "preventive": "idil/0cf2781f5396.m4a",
  "Investing in preventive care can reduce the number of people who need expensive hospital treatment later.": "idil/e3de5a3cd236.m4a",
  "wellbeing": "idil/9906f67fecd2.m4a",
  "Regular contact with friends and family is often linked to greater wellbeing in later life.": "idil/2a1dd717a053.m4a",
  "cohort": "idil/1e99e68d3b82.m4a",
