  "endoscopy": "idil/532ff2485592.m4a",
  "An endoscopy allows doctors to look directly at the lining of the stomach without major surgery.": "idil/199a338e1f40.m4a",
  "imaging": "idil/c6e642e2b148.m4a",
  "Advances in brain imaging have allowed researchers to observe which areas become active during a task.": "idil/8428018add7b.m4a",
  "screening": "idil/8246bb3203a9.m4a",
  "National screening programmes aim to detect certain cancers before patients notice any symptoms.": "idil/d5f213e70040.m4a",
  "genome": "idil/a5c9b737709f.m4a",
  "Sequencing a genome has become far cheaper and faster than it was at the start of this century.": "idil/8f82b9d04e74.m4a",
  "chlorophyll": "idil/199bae237c5e.m4a",
  "In autumn, many trees stop producing chlorophyll, revealing the yellow and orange pigments in their leaves.": "idil/f4b3d3a87f8b.m4a",
  "cellulose": "idil/37031a339038.m4a",
  "Cellulose gives plant cell walls their strength, and it is the main raw material for making paper.": "idil/54830e1ee70a.m4a",
  "microbe": "idil/2e6d60242831.m4a",
  "A single teaspoon of healthy soil may contain millions of microbes that help break down dead material.": "idil/9194a18fafba.m4a",
  "bacterium": "idil/db73600e9c39.m4a",
  "Under ideal conditions, a single bacterium can divide into two in less than half an hour.": "idil/25818777146e.m4a",
  "clone": "idil/5e0072329d50.m4a",
  "Gardeners have long produced a clone of a favourite plant simply by planting a cutting from it.": "idil/2f3111d38f16.m4a",
  "herbivore": "idil/d370bb9d434f.m4a",
  "Large herbivores such as elephants shape their environment by clearing paths and spreading seeds.": "idil/dc7089dbeb34.m4a",
  "carnivore": "idil/63cfae4e48bf.m4a",
  "As top carnivores, wolves help control the numbers of deer and other grazing animals.": "idil/520d5d78e1ed.m4a",
  "nocturnal": "idil/3c1338a4a464.m4a",
  "Many desert animals are nocturnal, avoiding the extreme heat by staying underground during the day.": "idil/33cf19f32990.m4a",
  "camouflage": "idil/136c3cec4a18.m4a",
  "The moth's pale wings provide effective camouflage against the bark of the trees where it rests.": "idil/f36a5b4c1509.m4a",
  "hibernate": "idil/8cf70a664387.m4a",
