  "Fish control their buoyancy with a gas-filled organ, which lets them stay at a chosen depth.": "idil/9596c39c9cd3.m4a",
  "Most land plants live in close partnership with fungi that grow around and inside their roots. The fungi, which spread through the soil in thin threads, collect water and minerals that the roots cannot reach. In return, the plant supplies the fungi with sugars produced by photosynthesis. Scientists have known about this partnership for more than a century. Some researchers have claimed that trees use these fungal networks to share food and to send warnings to one another. Other scientists, however, argue that the evidence for such claims is still weak. What most experts agree on is that soil fungi play an important role in the health of many forests and crops.": "idil/be699ef09976.m4a",
