  "Every autumn, hundreds of thousands of white storks cross Turkey on their way to Africa. For centuries, people watched them pass without knowing exactly where they spent the winter. In 2019, a team of biologists fitted small GPS trackers to forty young birds. While the storks were flying south, the trackers sent their positions every few minutes. This year, the team is studying a worrying change: some birds are stopping at rubbish dumps along the route instead of completing the journey. The researchers believe that this habit will spread if food waste remains easy to find. Next spring, they are going to tag another hundred birds to test the idea.": "idil/dcd4a42b4d72.m4a",
