  "Until the 1960s, the Aral Sea was one of the largest lakes in the world. From then on, much of the water of the two rivers that fed it was taken to irrigate cotton fields. By the end of the century, the lake had shrunk to less than half of its original size, and fishing towns that had depended on it for generations had lost their main source of income. Since 2005, when a dam was completed in the north, the water level in the northern basin has risen and some fish species have returned. Scientists have been monitoring the southern basin for decades. By the time it recovers, if it ever does, several generations will have passed.": "idil/4dc9bf3b50a7.m4a",
  "All visitors must sign in at the reception desk.": "idil/5e4dc619dcf9.m4a",
