  "Governments ought to invest more in early childhood education.": "idil/44f86d7081ff.m4a",
  "The ice on the lake is thin; you had better not walk on it.": "idil/bb27d3c4badb.m4a",
  "Most commuters would rather take the train than sit in traffic.": "idil/30365f4a0013.m4a",
  "Göbekli Tepe, near Şanlıurfa, is more than 11,000 years old. Its huge stone pillars, some over five metres tall, must have required the work of many people, so the site can't have been built by a single family. Most researchers believe that its builders still lived mainly by hunting and gathering. The site was long described as a temple, but recent excavations suggest that people may also have lived there. Some questions might never be answered, because writing had not yet been invented. Future excavations should shed more light on daily life at the site. Meanwhile, the fragile pillars had to be protected, so a large roof was built over the main enclosures.": "idil/e1b61e470d47.m4a",
  "Thousands of blood samples are analysed in this laboratory every day.": "idil/4120aa8e10d9.m4a",
  "The main road was closed after the landslide.": "idil/05d44569a4e3.m4a",
  "The bones were found by a group of schoolchildren on a field trip.": "idil/1070d69b621d.m4a",
  "The new terminal is due to be completed in 2027.": "idil/14981abab5dd.m4a",
  "Several participants complained about being interrupted during the interviews.": "idil/9f1e40f89b8d.m4a",
  "The letter seems to have been damaged by water at some point.": "idil/7a1ecd8cb730.m4a",
  "In 1900, an ancient shipwreck was discovered by sponge divers off the Greek island of Antikythera, and in 1901 a corroded bronze device was recovered from it. The device is thought to have been made in the second or first century BC, and it is believed to have been used to predict eclipses and the movements of the Sun and Moon. For decades, its gears could not be examined without damaging the fragile pieces. In 2005, however, the fragments were scanned with X-rays, which allowed many hidden inscriptions to be read for the first time. The mechanism is still being studied, and researchers continue to debate how its missing parts should be reconstructed.": "idil/d206a096b5b5.m4a",
  "Monitoring air quality near schools has become a priority for many cities.": "idil/7edaad5bf8af.m4a",
  "The aim of the survey is to map every spring in the valley.": "idil/7ced74e4fc4e.m4a",
