  "The old bridge was too narrow for lorries to cross.": "idil/1056ab616ba2.m4a",
  "Few villagers earned enough money to send their children to university.": "idil/b16ec40ee2a5.m4a",
  "Many students avoid testing themselves before an exam, because rereading their notes feels easier and safer. Yet memory research tends to point the other way: trying to recall information, even unsuccessfully, helps learners remember it later, especially when they check the answer afterwards. In one well-known experiment, students who practised recall instead of rereading remembered noticeably more a week later. It is not easy for teachers to change such habits, however. Students are used to judging their progress by how familiar a text feels, and familiarity is too unreliable to serve as a guide. Some teachers therefore encourage students to write short quizzes for one another, an approach that is cheap enough to use in almost any classroom.": "idil/4b4deaf62b96.m4a",
  "The survey collected information on the eating habits of 2,000 families.": "idil/c6b012e06c06.m4a",
  "There is growing evidence that noise at night affects the health of people living near airports.": "idil/6193d13580d9.m4a",
  "The new equipment was delivered to the laboratory last week.": "idil/748f02737f56.m4a",
  "The nurse gave the new parents a useful piece of advice: keep a simple diary of the baby's sleep.": "idil/226a0eb094e4.m4a",
  "The number of hospital beds per person has fallen in several countries.": "idil/6d210d724b4d.m4a",
