  "Quite a few readers wrote to the newspaper to complain.": "idil/3318a1b72928.m4a",
  "Most of the world's leading food crops benefit, at least in part, from animal pollination, and bees carry out much of this work. In some regions, such as parts of north-western Europe and North America, the number of wild bees has fallen in recent decades. A number of causes have been proposed, including habitat loss, pesticides and disease, but none of them seems to explain the decline on its own. Researchers also point out that little is known about many tropical species, because few long-term studies have been carried out there. Each new survey adds valuable data, yet a great deal of research is still needed before reliable conclusions can be drawn for every region.": "idil/496e586f1240.m4a",
  "The ministry published the new curriculum in May, but few teachers have read it so far.": "idil/52303e04df8d.m4a",
  "Tomatoes were brought to Europe from the Americas, and at first many people believed they were poisonous.": "idil/3f3d2cfae653.m4a",
  "Doctors asked the patients to keep a diary and to record their sleep every night.": "idil/75d799580dd6.m4a",
  "Some hospitals now send heart patients home with a small sensor that records their heartbeat. This approach reduces the number of follow-up visits.": "idil/32411efe4e2a.m4a",
  "Children who slept less than eight hours scored lower on memory tests. These findings suggest that sleep plays a role in learning.": "idil/27633e416cd2.m4a",
  "Global sea levels have risen by about 20 centimetres since 1900. This rise already threatens several low-lying coastal cities.": "idil/fe6751adece0.m4a",
  "Kepler and Galileo both argued that the Earth moves around the Sun, but only the former described the planetary orbits as ellipses.": "idil/2541e0ac861c.m4a",
