  "Volunteers were told that they could stop the experiment whenever they wished, but none of them did so.": "idil/ffb0bca2fd5f.m4a",
  "When the mines closed, many workers moved to the city, and years later their children did the same.": "idil/15c39fa2f956.m4a",
  "Sea otters and sea urchins share the kelp forests of the North Pacific, but the former feed on the latter. When fur traders hunted otters almost to extinction in the eighteenth and nineteenth centuries, the urchins multiplied, and in many areas they stripped the sea floor of kelp. This chain of events shows how the loss of a single predator can change a whole ecosystem. Such effects are known as trophic cascades. In many places where otters have returned, kelp forests have recovered, although their growth also depends on other factors, such as water temperature. It is likely that similar cascades occur in many other habitats, but they are often harder to observe than those on the Pacific coast.": "idil/6458aae8141f.m4a",
  "Lake Van is the largest lake in Türkiye.": "idil/a90790e92ff4.m4a",
  "Malaria is still one of the most serious diseases in many tropical countries.": "idil/527eed0bb49c.m4a",
  "Of the three methods tested, drip irrigation used the least water.": "idil/703b89794c38.m4a",
