  "The higher the altitude, the lower the air pressure.": "idil/c128588ba8a9.m4a",
  "Electric cars are becoming more and more common in European cities.": "idil/d7d6bf134645.m4a",
  "In 1847, the biologist Carl Bergmann observed that, among related warm-blooded animals, those in colder regions tend to be larger than their relatives in warmer ones. The usual explanation is geometric: the bigger an animal is, the smaller its surface area is relative to its volume. A large body therefore loses heat more slowly than a small one. The moose of northern Sweden are on average heavier than those of southern Sweden. However, the pattern is far less reliable in some groups than in others, and many species show no clear trend. Food supply can be just as important as temperature. Bergmann's rule is best seen as one of the best-known tendencies in ecology rather than as a strict law.": "idil/f67aca040e96.m4a",
  "Nurses who work night shifts are more likely to have sleep problems.": "idil/64165de815a8.m4a",
  "Volcanoes which erupt frequently are monitored from space.": "idil/1e5a68113a8e.m4a",
